#include <stdio.h>
#include <stdbool.h>
#include <string.h>

int L, C, P;
int black[6][6];
int leftIndex[6][6], rightIndex[6][6];
bool adj[36][36];
int matchR[36];
bool seen[36];

bool dfs(int u, int rightCount) {
    for (int v = 0; v < rightCount; v++) {
        if (adj[u][v] && !seen[v]) {
            seen[v] = true;
            if (matchR[v] == -1 || dfs(matchR[v], rightCount)) {
                matchR[v] = u;
                return true;
            }
        }
    }
    return false;
}

int main() {
    scanf("%d %d", &L, &C);
    scanf("%d", &P);

    memset(black, 0, sizeof(black));

    for (int i = 0; i < P; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        black[x - 1][y - 1] = 1;
    }

    memset(leftIndex, -1, sizeof(leftIndex));
    memset(rightIndex, -1, sizeof(rightIndex));

    int leftCount = 0, rightCount = 0;
    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};

    for (int r = 0; r < L; r++) {
        for (int c = 0; c < C; c++) {
            if (black[r][c]) continue;

            bool hasBlackNeighbor = false;
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < L && nc >= 0 && nc < C && black[nr][nc]) {
                    hasBlackNeighbor = true;
                    break;
                }
            }

            if (hasBlackNeighbor) {
                if ((r + c) % 2 == 0) {
                    leftIndex[r][c] = leftCount++;
                } else {
                    rightIndex[r][c] = rightCount++;
                }
            }
        }
    }

    memset(adj, 0, sizeof(adj));

    for (int r = 0; r < L; r++) {
        for (int c = 0; c < C; c++) {
            int u = leftIndex[r][c];
            if (u == -1) continue;

            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < L && nc >= 0 && nc < C) {
                    int v = rightIndex[nr][nc];
                    if (v != -1) {
                        adj[u][v] = true;
                    }
                }
            }
        }
    }

    memset(matchR, -1, sizeof(matchR));

    int matching = 0;
    for (int u = 0; u < leftCount; u++) {
        memset(seen, 0, sizeof(seen));
        if (dfs(u, rightCount)) {
            matching++;
        }
    }

    int answer = leftCount + rightCount - matching;
    printf("%d\n", answer);

    return 0;
}
